(()=>{const f=facilities.find(x=>x.id==='moe_1010013');if(!f)return;const source='https://www.city.tomioka.lg.jp/www/contents/1000000000757/index.html';const note='富岡市清掃センター公式施設概要は焼却施設（112.5t/24h、56.25t/24h×2炉）の施工をJFEエンジニアリング株式会社と明記。現行社名での公式表記を保持し、当時商号は未確認。';if(!f.builder){f.builder='JFEエンジニアリング株式会社';f.builder_source=source;f.builder_scope=note;f.builder_research_status='自治体公式施設概要で施工確認済み';}else{f.builder_additional_research_note=[f.builder_additional_research_note,note].filter(Boolean).join(' ／ ');f.builder_additional_research_urls=[f.builder_additional_research_urls,source].filter(Boolean).join(' | ');}})();